insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_1_v1'
from (values
('114.32.c.1.A',1,'Which activity is a language learning activity in a Discovering Languages class?','["practicing greetings with a partner", "balancing a chemical equation", "sketching a bridge blueprint", "running a mile for time"]'::jsonb,0,'Language learning activities include listening, speaking, reading and writing practice.','original'),
('114.32.c.1.A',2,'A student plays a vocabulary matching game in a new language. Why is this useful?','["It replaces all grammar study forever.", "It builds word recognition through play.", "It proves the student is fluent.", "It avoids using the language."]'::jsonb,1,'Games give low-pressure practice with new words.','original'),
('114.32.c.1.B',2,'Two languages put adjectives in different places relative to nouns. What is the student doing by noticing this?','["editing a photograph", "measuring a distance", "comparing language structures", "calculating interest"]'::jsonb,2,'Comparing languages means noticing similarities and differences.','original'),
('114.32.c.1.B',3,'English and another language both use a word for greeting someone but pronounce it differently. This difference shows that languages can share ideas but vary in:','["the need for communication", "the meaning of all ideas", "the existence of greetings", "sounds and spelling"]'::jsonb,3,'Languages express similar ideas with different forms.','original'),
('114.32.c.1.C',2,'Which set lists the four basic communication skills in language study?','["listening, speaking, reading, writing", "painting, drawing, carving, molding", "adding, subtracting, dividing, rounding", "jumping, lifting, swimming, throwing"]'::jsonb,0,'Listening, speaking, reading and writing are the four skills.','original'),
('114.32.c.1.C',2,'A student reads a short sign in a new language and says what it means aloud. Which two skills are used?','["swimming and jumping", "reading and speaking", "drawing and painting", "adding and dividing"]'::jsonb,1,'Reading the sign and saying the meaning uses two skills.','original'),
('114.32.c.2.A',2,'Which is a cultural practice?','["a triangle''s area formula", "a rock sample", "a traditional holiday celebration", "the boiling point of water"]'::jsonb,2,'Cultural practices are shared customs of a group.','original'),
('114.32.c.2.A',3,'Studying how people in a region greet each other at a meal is learning about:','["tectonic plates", "atomic mass", "fractions", "cultural practices"]'::jsonb,3,'Customs of daily life are cultural practices.','original'),
('114.32.c.2.B',2,'Which of these is a cultural product?','["a traditional dish", "a handshake custom", "a belief about respect", "a family tradition"]'::jsonb,0,'Products are tangible things such as food, art and clothing.','original'),
('114.32.c.2.B',2,'A student examines traditional clothing from a region. This is an example of studying:','["chemical changes", "cultural products", "number lines", "weather patterns"]'::jsonb,1,'Clothing is a cultural product.','original'),
('114.32.c.2.C',3,'A student notes that both her family and a family in another country share meals on holidays, but eat different foods. This is:','["a spelling rule", "measuring volume", "comparing cultures", "a map scale"]'::jsonb,2,'Comparing cultures looks at likenesses and differences.','original'),
('114.32.c.2.C',3,'Which question best helps a student compare another culture to her own?','["What is 12 times 9?", "Which element is lightest?", "How tall is the tallest building?", "How is a school day there similar to and different from mine?"]'::jsonb,3,'Comparison questions look at both cultures.','original'),
('114.32.c.3.A',2,'Cognates are words that:','["look and sound similar and mean the same in two languages", "have opposite meanings", "exist in only one language", "are spelled backward"]'::jsonb,0,'Cognates help learners guess new vocabulary.','original'),
('114.32.c.3.A',3,'Recognizing that a word''s origin can be traced to a root shared with English helps a learner:','["avoid reading entirely", "guess the word''s meaning", "forget grammar", "lose the pattern"]'::jsonb,1,'Word origins are a useful learning strategy.','original'),
('114.32.c.3.B',3,'In some languages, a verb ending changes with the speaker. Noticing such a pattern is an example of awareness of:','["food groups", "map projection", "grammatical structure", "music tempo"]'::jsonb,2,'Grammar patterns include word endings and word order.','original'),
('114.32.c.3.B',3,'Some writing systems use characters instead of letters. This is a difference in:','["time zones", "boiling temperatures", "number bases", "symbol systems"]'::jsonb,3,'Writing systems differ across languages.','original'),
('114.33.c.1.A',1,'What is a polite way to introduce yourself in most cultures?','["Say hello and share your name.", "Say nothing and walk away.", "Shout a question about money.", "Turn your back."]'::jsonb,0,'Greetings and names start a respectful introduction.','original'),
('114.33.c.1.A',2,'Culturally appropriate greetings can include a bow, a handshake or a kiss on the cheek. This shows that:','["greetings are not important", "greeting customs differ by culture", "all cultures greet identically", "handshakes are illegal"]'::jsonb,1,'Customs vary, so learners must respect the local style.','original'),
('114.33.c.1.B',2,'Which is a simple question about personal preferences?','["How far is the moon?", "What is the area of a circle?", "What music do you like?", "When did the war end?"]'::jsonb,2,'Preference questions ask what someone likes.','original'),
('114.33.c.1.B',2,'A friend asks, Do you like soccer? A simple response is:','["The treaty was signed in May.", "Photosynthesis is a process.", "Seven is a prime number.", "Yes, I like it."]'::jsonb,3,'A short direct reply answers a preference question.','original'),
('114.33.c.1.C',2,'Which is essential information to exchange when meeting a new classmate?','["name, family and interests", "medical history", "bank balance", "a secret password"]'::jsonb,0,'Basic personal information is shared in introductions.','original'),
('114.33.c.1.C',3,'A student tells a partner how many people are in her family. This is exchanging information about:','["trade routes", "self and family", "geology", "music theory"]'::jsonb,1,'Family information is a familiar topic.','original'),
('114.33.c.2.A',2,'A student studies how families in a country celebrate a seasonal festival. This is learning about:','["computer coding", "triangle rules", "cultural practices and traditions", "plate tectonics"]'::jsonb,2,'Celebrations and traditions are cultural practices.','original'),
('114.33.c.2.A',3,'A cultural perspective is:','["a chemical reaction", "a kind of food", "a type of map", "a way of seeing the world shared by a group"]'::jsonb,3,'Perspectives are the beliefs and attitudes behind practices.','original'),
('114.33.c.2.B',3,'Which is a historic influence a culture might have on another?','["explorers bringing new foods and ideas", "a classroom clock", "a lunch menu", "a pencil color"]'::jsonb,0,'Exploration and trade spread cultures.','original'),
('114.33.c.2.B',3,'A contemporary influence from a culture could be:','["an ancient road", "a popular style of music spread through streaming", "a medieval treaty", "a stone tool"]'::jsonb,1,'Modern media spread cultural influence today.','original'),
('114.33.c.2.C',2,'Which pair includes cultural products?','["a custom and a belief", "a greeting and a handshake", "a traditional food and a style of clothing", "a rule and a value"]'::jsonb,2,'Products are things people make or use.','original'),
('114.33.c.2.C',3,'Describing the kinds of shelter families use in different regions is describing:','["languages only", "grammar rules", "musical notes", "products of a culture"]'::jsonb,3,'Shelter is a cultural product.','original'),
('114.33.c.3.A',2,'Which is an authentic material for learning about a culture?','["a map or newspaper from that country", "a made-up story with invented facts", "a random cartoon", "a blank worksheet"]'::jsonb,0,'Authentic materials come from the culture itself.','original'),
('114.33.c.3.A',3,'A graphic organizer helps a student:','["avoid reading", "sort and compare information", "skip research", "hide sources"]'::jsonb,1,'Organizers structure what a student learns.','original'),
('114.33.c.3.B',3,'A student shares findings about a culture. What should the research include?','["copied text without credit", "guesses only", "reliable sources and clear information", "unnamed rumors"]'::jsonb,2,'Good research uses credible sources.','original'),
('114.33.c.3.B',3,'Which topic could a student research and present as a cultural influence?','["the area of a square", "the boiling point of tea", "the plural of sheep", "how a festival changed over time"]'::jsonb,3,'Cultural influences can be traced through history.','original'),
('114.33.c.4.A',3,'Comparing traditions in two cultures helps a learner see:','["both similarities and differences", "nothing useful", "only similarities", "only differences"]'::jsonb,0,'Comparison reveals shared human themes and unique customs.','original'),
('114.33.c.4.A',3,'Daily life, such as meal times, can differ by culture. This is a difference in:','["alphabets", "practices", "continents", "time zones only"]'::jsonb,1,'Meal customs are cultural practices.','original'),
('114.33.c.4.B',3,'A false cognate is a word that:','["has no letters", "has the same meaning in both languages", "looks like a word in another language but means something different", "is spelled backward"]'::jsonb,2,'False cognates mislead learners.','original'),
('114.33.c.4.B',3,'An idiomatic expression is a phrase whose meaning:','["is a number", "is always literal", "is a map symbol", "is not the same as the literal words"]'::jsonb,3,'Idioms must be learned as units.','original'),
('114.33.c.4.C',3,'A student watches an advertisement from another country. What can it show about that culture?','["values, products and customs it highlights", "nothing about the culture", "only the weather", "only the price of gas"]'::jsonb,0,'Media reflect cultural views.','original'),
('114.33.c.4.C',3,'Which media source could a student analyze to learn about cultural values?','["a blank notebook", "a newspaper or television program from that region", "a recipe for glue", "a math worksheet"]'::jsonb,1,'News and television show cultural representation.','original'),
('114.33.c.5.A',2,'A student visits an online festival from another country and then discusses it. This is:','["avoiding learning", "a spelling quiz", "participating in a cultural event", "a lab report"]'::jsonb,2,'Cultural events can be local, global or online.','original'),
('114.33.c.5.A',3,'After attending a cultural event, a student should discuss:','["unrelated sports scores", "a math test", "only the weather", "experiences and perspectives"]'::jsonb,3,'Reflection builds understanding.','original'),
('114.33.c.5.B',2,'Which career might need cross-cultural awareness and language skills?','["an international tour guide", "a solitary night watchman only", "a clock repair hobbyist", "a plumber working alone with no customers ever"]'::jsonb,0,'Many careers involve working with people from other cultures.','original'),
('114.33.c.5.B',3,'A student researching careers in translation is exploring jobs that use:','["only athletics", "language skills", "only drawing", "only math"]'::jsonb,1,'Translators rely on language skills.','original'),
('114.33.c.5.C',3,'Learning about other cultures can help personal growth by:','["ending all disagreements", "making others unwelcome", "building empathy and open-mindedness", "reducing curiosity"]'::jsonb,2,'Cultural awareness supports understanding of others.','original'),
('114.33.c.5.C',3,'Which attitude shows cultural awareness?','["laughing at unfamiliar clothing", "assuming your way is always best", "refusing to listen", "respecting customs that differ from your own"]'::jsonb,3,'Respect is key to cultural awareness.','original'),
('114.34.c.1.A',2,'In ASL class, two students exchange signs to share where they live. This is an example of:','["an ASL exchange to give and get information", "a written spelling test", "a map drawing", "a lab experiment"]'::jsonb,0,'Exchanges provide and obtain information.','original'),
('114.34.c.1.A',3,'Which communication goal fits an ASL exchange of learned material?','["memorizing a chemical table", "socializing and sharing information", "running a race", "avoiding all eye contact"]'::jsonb,1,'Exchanges are used to socialize and share information.','original'),
('114.34.c.1.B',2,'Understanding a brief instruction in ASL, such as a signed command, is part of:','["learning to draw", "solving equations", "comprehending basic ASL", "playing a sport"]'::jsonb,2,'Beginners understand simple stories and commands.','original'),
('114.34.c.1.B',3,'Which is a basic ASL comprehension task at the novice level?','["reading a legal contract", "translating a long novel", "debating foreign policy", "following a short signed direction"]'::jsonb,3,'Novice learners understand brief everyday signs.','original'),
('114.34.c.1.C',3,'A classifier in ASL is used to:','["show the movement, shape or location of an object", "spell a word letter by letter only", "end a sentence", "write in English"]'::jsonb,0,'Classifiers represent categories of objects and how they move.','original'),
('114.34.c.1.C',3,'Which of these shows conveying information in ASL without voice?','["writing a note only", "signing a short phrase using familiar words and classifiers", "speaking aloud to a hearing partner", "whispering in English"]'::jsonb,1,'ASL conveys meaning through signs, facial expressions and movement.','original'),
('114.34.c.1.D',3,'ASL phonology refers to the parts of a sign, such as:','["paper size", "tense and mood only", "handshape, location and movement", "alphabet letters in a book"]'::jsonb,2,'Phonology in ASL involves handshape, location, movement and orientation.','original'),
('114.34.c.1.D',3,'Which term means the rules for how signs are ordered in sentences?','["morphology", "phonology", "semantics", "syntax"]'::jsonb,3,'Syntax is the order and arrangement of signs.','original'),
('114.34.c.1.E',3,'A handshape story in ASL literature uses:','["a series of signs sharing the same handshape", "only spoken English", "a printed rhyme", "a sound pattern"]'::jsonb,0,'Handshape stories are an ASL art form.','original'),
('114.34.c.1.E',3,'Experiencing ASL literature gives students exposure to:','["computer menus", "traditional features of Deaf cultural storytelling", "music scales", "only sports reports"]'::jsonb,1,'ASL literature reflects Deaf culture.','original'),
('114.34.c.2.A',2,'To get a Deaf person''s attention in a respectful way, a signer can:','["turn off the lights", "throw an object", "wave or tap the shoulder", "shout loudly"]'::jsonb,2,'Tapping or waving are accepted attention-getting norms.','original'),
('114.34.c.2.A',3,'In Deaf culture, maintaining eye contact during a conversation shows:','["rudeness", "confusion", "boredom", "attention and respect"]'::jsonb,3,'Eye contact is essential in visual communication.','original'),
('114.34.c.2.B',3,'Appreciating ASL poetry or storytelling helps learners understand:','["the perspectives of the Deaf community", "only grammar rules", "nothing about culture", "music notation"]'::jsonb,0,'Literature expresses cultural views.','original'),
('114.34.c.2.B',3,'Which is an example of ASL literature created by the Deaf?','["a phone manual", "a signed story or poem", "a city map", "a printed math table"]'::jsonb,1,'Signed art forms are ASL literature.','original'),
('114.34.c.2.C',3,'Which contribution by the Deaf community has shaped communication and education?','["writing a famous opera", "inventing the compass", "development of sign language and Deaf schools", "building the first airplane"]'::jsonb,2,'Deaf communities created sign languages and schools.','original'),
('114.34.c.2.C',3,'Recognizing contributions by Deaf individuals helps students:','["stop signing", "avoid ASL", "ignore history", "value Deaf achievements"]'::jsonb,3,'Appreciation of contributions builds respect.','original'),
('114.34.c.2.D',3,'Learning about the history of Deaf education helps students understand:','["how Deaf culture developed", "only math history", "only art styles", "none of this"]'::jsonb,0,'History explains the roots of today''s Deaf culture.','original'),
('114.34.c.2.D',3,'Deaf history is important to American Deaf culture because it:','["is unrelated to ASL", "shapes shared identity and values", "has no effect", "only concerns hearing people"]'::jsonb,1,'History informs community identity.','original'),
('114.34.c.3.A',2,'A student uses a video library to learn new signs. This is:','["avoiding resources", "a spelling bee", "using digital technology to access ASL information", "a science fair"]'::jsonb,2,'Digital resources can supply signing examples.','original'),
('114.34.c.3.A',3,'Which is a resource for learning about Deaf culture online?','["an unrelated game", "a cooking show", "a random advertisement", "a Deaf community organization''s website"]'::jsonb,3,'Reliable online resources share Deaf culture information.','original'),
('114.34.c.3.B',3,'A student uses ASL to learn about weather in science class. This is:','["using ASL to expand knowledge of other subjects", "avoiding science", "a dictionary game", "a grammar drill"]'::jsonb,0,'ASL can connect to other subjects.','original'),
('114.34.c.3.B',3,'Learning the signs for numbers can support:','["only gym", "math class", "nothing", "only art class"]'::jsonb,1,'Number signs connect to math.','original'),
('114.34.c.4.A',3,'Comparing English sentence order with ASL sentence order helps a student understand:','["only baking", "only music", "the nature of language", "only maps"]'::jsonb,2,'Comparing languages reveals how language works.','original'),
('114.34.c.4.A',3,'ASL has its own grammar that is:','["identical to English grammar", "not a real grammar", "spoken only", "different from English grammar"]'::jsonb,3,'ASL is a complete language with its own rules.','original'),
('114.34.c.4.B',3,'Comparing Deaf culture norms with the student''s own culture helps show:','["how cultures have different values and customs", "that culture does not exist", "that all cultures are identical", "nothing at all"]'::jsonb,0,'Cultural comparison builds awareness.','original'),
('114.34.c.4.B',3,'A hearing student might notice that Deaf people value:','["loud speech", "visual communication and eye contact", "phone calls only", "radio talk shows"]'::jsonb,1,'Deaf culture is visually oriented.','original'),
('114.34.c.4.C',3,'Which shows one language and culture influencing another?','["a weather forecast", "a rock sample", "English speakers adopting some ASL signs or gestures", "two unrelated languages never meeting"]'::jsonb,2,'Languages borrow from each other.','original'),
('114.34.c.4.C',3,'When ASL signs and English words are both used by a bilingual signer, the languages can:','["cancel each other", "disappear", "become math", "influence each other"]'::jsonb,3,'Contact between languages causes influence.','original'),
('114.34.c.5.A',3,'Using ASL at a school club event is an example of:','["applying ASL outside class", "avoiding practice", "silent reading", "a written exam"]'::jsonb,0,'Using ASL in activities builds skills.','original'),
('114.34.c.5.A',3,'At the novice level, a student can use ASL to:','["teach a university course", "share basic information and greetings", "debate complex law", "interpret a courtroom trial"]'::jsonb,1,'Novice level means simple, familiar communication.','original'),
('114.34.c.5.B',2,'Which technology helps people communicate with the Deaf community?','["a metronome", "a protractor", "video relay and video calls", "a thermometer"]'::jsonb,2,'Video technology supports signed communication.','original'),
('114.34.c.5.B',3,'Closed captioning helps Deaf people by:','["removing pictures", "making video louder", "muting the screen", "showing spoken words as text"]'::jsonb,3,'Captions provide access to audio content.','original'),
('114.34.c.5.C',3,'A lifelong learner of ASL might:','["keep practicing signs for enjoyment", "avoid the Deaf community", "stop learning after class", "never sign again"]'::jsonb,0,'Lifelong learning means ongoing use for enrichment.','original'),
('114.34.c.5.C',3,'Using ASL for personal enrichment means using it to:','["skip practice", "enjoy and grow beyond school requirements", "avoid people", "pass only one test"]'::jsonb,1,'Enrichment is personal growth.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
